import React, { useEffect, useState } from "react";
import { ethers } from "ethers";
import contractABI from "../abi/votingABI";
import contractAddress from "../contractAddress"; // replace with actual address file or string

const ResultsPage = () => {
  const [candidates, setCandidates] = useState([]);

  useEffect(() => {
    const loadResults = async () => {
      try {
        const provider = new ethers.BrowserProvider(window.ethereum);
        const contract = new ethers.Contract(contractAddress, contractABI, provider);
        const count = await contract.getCandidateCount();

        const data = [];
        for (let i = 0; i < count; i++) {
          const name = await contract.getCandidateName(i);
          const votes = await contract.getVoteCount(i);
          data.push({ name, votes: votes.toString() });
        }
        setCandidates(data);
      } catch (error) {
        console.error("Error loading results", error);
      }
    };

    loadResults();
  }, []);

  return (
    <div className="container mt-5">
      <h2 className="mb-4">Election Results</h2>
      <table className="table table-striped table-bordered shadow">
        <thead className="thead-dark">
          <tr>
            <th>#</th>
            <th>Candidate Name</th>
            <th>Votes</th>
          </tr>
        </thead>
        <tbody>
          {candidates.map((candidate, index) => (
            <tr key={index}>
              <td>{index + 1}</td>
              <td>{candidate.name}</td>
              <td>{candidate.votes}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
};

export default ResultsPage;
